import React from 'react'
import classes from './SocialMedia.module.scss'

const SocialMedia = () => {
    return (
        <contaiber className={classes.s}>
            <img className={classes.img} src="../img/Mail.svg" alt="Mail" /> 
            <img className={classes.img} src="../img/tg.svg" alt="tg" /> 
            <img className={classes.img} src="../img/Whatsap.svg" alt="Whatsap" /> 
            <img className={classes.img} src="../img/Vk.svg" alt="Vk" /> 
        </contaiber>
    )
}

export default SocialMedia
